// Reproduces crates/deck-remote/tests/vectors/api-form.json (generated by the Rust side, pinned in
// crates/deck-remote/tests/wire_freeze.rs): the `form` answer encodes canonically, the `form`
// request of a live session and the welcome listing `form` decode to exactly the wire value, and
// malformed form answers are never sent as such.

import { describe, expect, test } from 'bun:test';
import { readFileSync } from 'node:fs';

import {
  checkRequest,
  decodeEvent,
  decodeReply,
  decodeWelcome,
  FEATURE_FORM,
  FEATURE_PROGRESS,
  FEATURE_S4,
  opJournaled,
  PROTOCOL,
  type Request,
  requestJson,
} from '../src/remote/api.ts';
import { utf8 } from '../src/remote/bytes.ts';
import { DEVICE_FEATURES } from '../src/app/client.ts';

interface FormVectors {
  protocol: number;
  features: string[];
  messages: { type: 'request' | 'reply' | 'event' | 'welcome'; case: string; json: string }[];
  rejected_requests: { case: string; json: string; error: string; id: number }[];
}

const vectors: FormVectors = JSON.parse(
  readFileSync(new URL('../../crates/deck-remote/tests/vectors/api-form.json', import.meta.url), 'utf8'),
);

test('protocol version and form features stay frozen; the app also announces progress', () => {
  expect(vectors.protocol).toBe(PROTOCOL);
  expect(vectors.features).toEqual([FEATURE_S4, FEATURE_FORM]);
  expect(DEVICE_FEATURES).toEqual([...vectors.features, FEATURE_PROGRESS]);
});

describe('form answers encode canonically', () => {
  const requests = vectors.messages.filter((m) => m.type === 'request');
  test('the vectors carry requests', () => expect(requests.length).toBeGreaterThan(0));
  for (const vector of requests) {
    test(vector.case, () => {
      const request: Request = JSON.parse(vector.json);
      expect(checkRequest(request)).toBeNull();
      expect(requestJson(request)).toBe(vector.json);
      expect(request.seq !== null && request.seq !== undefined).toBe(opJournaled(request.op));
    });
  }

  test('an absent Other is written as null', () => {
    expect(
      requestJson({
        id: 1,
        seq: 2,
        op: {
          op: 'answer_ui',
          live: { key: 'k', generation: 1 },
          request: 'u-1',
          value: { type: 'form', fields: [{ checked: [0], type: 'choice' }, { text: 'x', type: 'text' }] },
        },
      }),
    ).toBe(
      '{"id":1,"seq":2,"op":{"op":"answer_ui","live":{"key":"k","generation":1},"request":"u-1",' +
        '"value":{"type":"form","fields":[{"type":"choice","checked":[0],"other":null},{"type":"text","text":"x"}]}}}',
    );
  });
});

describe('form gateway messages validate', () => {
  const decoders = { reply: decodeReply, event: decodeEvent, welcome: decodeWelcome } as const;
  for (const type of ['reply', 'event', 'welcome'] as const) {
    for (const vector of vectors.messages.filter((m) => m.type === type)) {
      test(`${type} ${vector.case}`, () => {
        const value = decoders[type](utf8(vector.json));
        const parsed: unknown = JSON.parse(vector.json);
        expect(parsed).toEqual(value);
        // Same keys in the same order as Rust wrote them, `form` only when present.
        expect(JSON.stringify(value)).toBe(JSON.stringify(parsed));
      });
    }
  }

  test('the live vector carries a form request', () => {
    const live = vectors.messages.find((m) => m.type === 'event' && m.json.includes('"kind":"form"'));
    expect(live).toBeDefined();
  });
});

test('rejected form answers are never sent as such', () => {
  // Each fails checkRequest the way the gateway would refuse it, except unknown fields, which
  // the canonical encoding drops (the typed request cannot carry them).
  expect(vectors.rejected_requests.length).toBeGreaterThan(0);
  for (const vector of vectors.rejected_requests) {
    const request: Request = JSON.parse(vector.json);
    if (vector.case.startsWith('unknown field')) {
      expect(requestJson(request)).not.toBe(vector.json);
    } else {
      expect(checkRequest(request)).not.toBeNull();
    }
  }
});
